import { useState } from "react";
import "./Services.css";

function Services() {
  const [selectedService, setSelectedService] = useState(null); // Currently selected service
  const [isModalOpen, setIsModalOpen] = useState(false);

  // Service details data
  const serviceInfo = {
    "2-Wheeler Driving Training": {
      documents: "ID Proof, Address Proof",
      price: "₹2000",
      duration: "1 Month",
      description: "Learn driving 2-wheelers with certified trainers."
    },
    "4-Wheeler Driving Training": {
      documents: "ID Proof, Address Proof, Learner's License",
      price: "₹4000",
      duration: "1.5 Months",
      description: "Learn driving 4-wheelers with practical lessons."
    },
    "Fast Tag": {
      documents: "Vehicle RC, ID Proof",
      price: "₹500",
      duration: "1 Day",
      description: "Get your Fast Tag for toll payments."
    },
    "License Renewal": {
      documents: "Old License, ID Proof",
      price: "₹300",
      duration: "1 Day",
      description: "Renew your driving license easily."
    },
    "Vehicle Passing": {
      documents: "Vehicle RC, Insurance, ID Proof",
      price: "₹1500",
      duration: "2 Days",
      description: "Vehicle passing for new or modified vehicles."
    },
    "Other Driving Courses": {
      documents: "Depends on course",
      price: "Varies",
      duration: "Varies",
      description: "Specialized driving courses for advanced skills."
    }
  };

  // Open modal with selected service
  const openModal = (service) => {
    setSelectedService(service);
    setIsModalOpen(true);
  };

  // Close modal
  const closeModal = () => {
    setSelectedService(null);
    setIsModalOpen(false);
  };

  return (
    <div className="services">
      <h2>Our Services</h2>
      <div className="service-cards">
        {Object.keys(serviceInfo).map((service) => (
          <div
            key={service}
            className="card"
            onClick={() => openModal(service)}
          >
            {service}
          </div>
        ))}
      </div>

      {/* Modal */}
      {isModalOpen && selectedService && (
        <div className="modal-overlay" onClick={closeModal}>
          <div className="modal-content" onClick={(e) => e.stopPropagation()}>
            <h3>{selectedService}</h3>
            <pre>
Documents Required: {serviceInfo[selectedService].documents}
Price: {serviceInfo[selectedService].price}
Duration: {serviceInfo[selectedService].duration}
Description: {serviceInfo[selectedService].description}
            </pre>
            <button onClick={closeModal}>Close</button>
          </div>
        </div>
      )}
    </div>
  );
}

export default Services;
